import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { rhGetUser } from '@/lib/rh-auth';
import {
  enrichFuncionario,
  CAMPOS_COMPOSICAO_HISTORICO,
  formatComposicaoHistorico,
} from '@/lib/rh-funcionario';
import { calcularComposicaoSalarial } from '@/lib/calculos-rh';
import { carregarBonificacoesComposicao } from '@/lib/rh-bonificacoes-composicao';
import { limparCPF, validarCPF, validarDataNascimento } from '@/lib/validacoes';
import {
  inicioAquisitivoAposGozo,
  inicioAquisitivoEfetivo,
  sameUtcDay,
} from '@/lib/ferias-rh';

export const dynamic = 'force-dynamic';


const INCLUDE = {
  cargo: { select: { id: true, nome: true, ratPct: true } },
  loja: { select: { id: true, nome: true, fap: true } },
} as const;

const CAMPOS_HISTORICO = [
  ...CAMPOS_COMPOSICAO_HISTORICO,
  'cargoId',
  'lojaId',
  'escala',
  'turno',
  'ativo',
] as const;
type CampoHistorico = (typeof CAMPOS_HISTORICO)[number];

function valorParaString(
  campo: CampoHistorico,
  valor: unknown,
  existing?: Record<string, unknown>
): string {
  if (valor === null || valor === undefined) return '';
  if (campo === 'cargoResponsabilidade') return valor ? 'Sim' : 'Não';
  if (typeof valor === 'boolean') return valor ? 'Ativo' : 'Inativo';
  if (
    campo === 'salarioBase' ||
    campo === 'bonificacaoAssiduidade' ||
    campo === 'valorAlimentacao' ||
    campo === 'valorVT'
  ) {
    return `R$ ${Number(valor).toFixed(2)}`;
  }
  if (CAMPOS_COMPOSICAO_HISTORICO.includes(campo as (typeof CAMPOS_COMPOSICAO_HISTORICO)[number])) {
    return '';
  }
  return String(valor);
}

function composicaoSnapshot(data: {
  salarioBase: number;
  cargoResponsabilidade: boolean;
  bonificacaoAssiduidade: number;
  valorAlimentacao: number;
  valorVT: number;
}) {
  return formatComposicaoHistorico(calcularComposicaoSalarial(data));
}

function calcDatasExperiencia(dataAdmissao: Date) {
  const d1 = new Date(dataAdmissao);
  d1.setDate(d1.getDate() + 45);
  const d2 = new Date(dataAdmissao);
  d2.setDate(d2.getDate() + 90);
  return { dataFimExperiencia1: d1, dataFimExperiencia2: d2 };
}

export async function GET(_req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  try {
    const { id } = await params;
    const rh = await rhGetUser();
    if (!rh) return NextResponse.json({ error: 'Não autorizado' }, { status: 401 });

    let funcionario = await prisma.rhFuncionario.findFirst({
      where: { id, userId: rh!.userId },
      include: INCLUDE,
    });

    if (!funcionario)
      return NextResponse.json({ error: 'Funcionário não encontrado' }, { status: 404 });

    // Corrige legado: gozo registrado sem avançar o período aquisitivo
    if (
      funcionario.dataInicioFerias &&
      funcionario.dataAdmissao &&
      funcionario.dataGozoFerias
    ) {
      const efetivo = inicioAquisitivoEfetivo(
        funcionario.dataInicioFerias,
        funcionario.dataAdmissao,
        funcionario.dataGozoFerias,
      );
      if (efetivo.getTime() !== new Date(funcionario.dataInicioFerias).getTime()) {
        funcionario = await prisma.rhFuncionario.update({
          where: { id },
          data: { dataInicioFerias: efetivo },
          include: INCLUDE,
        });
      }
    }

    const bonificacoesComposicao = await carregarBonificacoesComposicao(id);

    return NextResponse.json(
      enrichFuncionario(
        funcionario,
        funcionario.cargo?.ratPct ?? 1.0,
        funcionario.loja?.fap ?? 1.0,
        bonificacoesComposicao
      )
    );
  } catch (err) {
    console.error('[GET /api/rh/funcionarios/[id]]', err);
    return NextResponse.json({ error: 'Erro interno' }, { status: 500 });
  }
}

export async function PATCH(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  try {
    const { id } = await params;
    const rh = await rhGetUser();
    if (!rh) return NextResponse.json({ error: 'Não autorizado' }, { status: 401 });

    const existing = await prisma.rhFuncionario.findFirst({
      where: { id, userId: rh!.userId },
    });
    if (!existing)
      return NextResponse.json({ error: 'Funcionário não encontrado' }, { status: 404 });

    const body = await req.json();
    const {
      nome,
      cpf: cpfRaw,
      email,
      telefone,
      dataNascimento,
      dataAdmissao,
      cargoId,
      lojaId,
      salarioBase,
      valorAlimentacao,
      valorVT,
      cargoResponsabilidade,
      bonificacaoAssiduidade,
      escala,
      turno,
      horarioEntrada,
      horarioSaida,
      horarioDigest,
      diasFolga,
      domingoFolga,
      observacoes,
      ativo,
      dataGozoFerias,
      statusFerias,
      diasFeriasGozados,
      motivo,
      numeroFolha: numeroFolhaRaw,
    } = body;
    const numeroFolhaNorm =
      numeroFolhaRaw !== undefined ? (numeroFolhaRaw?.trim() || null) : undefined;

    // Normaliza strings vazias de campos opcionais (form manda "" em vez de null)
    const cpfLimpo =
      cpfRaw !== undefined ? limparCPF(String(cpfRaw || '')) : undefined;
    const nascStr =
      dataNascimento !== undefined
        ? (dataNascimento ? String(dataNascimento) : null)
        : undefined;
    const admissaoStr =
      dataAdmissao !== undefined
        ? (dataAdmissao ? String(dataAdmissao) : null)
        : undefined;
    const cargoIdNorm =
      cargoId !== undefined ? (cargoId ? String(cargoId) : null) : undefined;
    const lojaIdNorm =
      lojaId !== undefined ? (lojaId ? String(lojaId) : null) : undefined;

    if (cpfLimpo !== undefined) {
      if (cpfLimpo) {
        if (!validarCPF(cpfLimpo))
          return NextResponse.json({ error: 'CPF inválido' }, { status: 400 });
        const dup = await prisma.rhFuncionario.findFirst({
          where: { userId: rh!.userId, cpf: cpfLimpo, ativo: true, id: { not: id } },
        });
        if (dup) return NextResponse.json({ error: 'CPF já cadastrado' }, { status: 409 });
      }
    }

    if (nascStr) {
      const nasc = new Date(nascStr);
      if (Number.isNaN(nasc.getTime()))
        return NextResponse.json({ error: 'Data de nascimento inválida' }, { status: 400 });
      const errNasc = validarDataNascimento(nasc);
      if (errNasc) return NextResponse.json({ error: errNasc }, { status: 400 });
    }

    if (numeroFolhaNorm !== undefined && numeroFolhaNorm) {
      const folhaDup = await prisma.rhFuncionario.findFirst({
        where: { userId: rh!.userId, numeroFolha: numeroFolhaNorm, id: { not: id } },
        select: { id: true },
      });
      if (folhaDup)
        return NextResponse.json({ error: 'N° da folha já cadastrado em outro funcionário' }, { status: 409 });
    }

    if (salarioBase !== undefined && Number(salarioBase) <= 0)
      return NextResponse.json({ error: 'Salário base inválido' }, { status: 400 });

    let experienciaData: Record<string, Date> = {};
    if (admissaoStr) {
      const admissao = new Date(admissaoStr);
      if (Number.isNaN(admissao.getTime()))
        return NextResponse.json({ error: 'Data de admissão inválida' }, { status: 400 });

      const { dataFimExperiencia1, dataFimExperiencia2 } = calcDatasExperiencia(admissao);
      experienciaData = {
        dataInicioExperiencia: admissao,
        dataFimExperiencia1,
        dataFimExperiencia2,
      };

      // Só reinicia o período aquisitivo se a admissão mudou de fato
      const admissaoMudou =
        !existing.dataAdmissao ||
        !sameUtcDay(admissao, new Date(existing.dataAdmissao));
      if (admissaoMudou) {
        experienciaData.dataInicioFerias = existing.dataGozoFerias
          ? inicioAquisitivoAposGozo(existing.dataGozoFerias, {
              dataAdmissao: admissao,
              dataInicioFerias: admissao,
            })
          : admissao;
      }
    }

    const composicaoAntes = composicaoSnapshot(existing);
    const merged = {
      salarioBase: salarioBase !== undefined ? Number(salarioBase) : existing.salarioBase,
      cargoResponsabilidade:
        cargoResponsabilidade !== undefined
          ? Boolean(cargoResponsabilidade)
          : existing.cargoResponsabilidade,
      bonificacaoAssiduidade:
        bonificacaoAssiduidade !== undefined
          ? Number(bonificacaoAssiduidade)
          : existing.bonificacaoAssiduidade,
      valorAlimentacao:
        valorAlimentacao !== undefined ? Number(valorAlimentacao) : existing.valorAlimentacao,
      valorVT: valorVT !== undefined ? Number(valorVT) : existing.valorVT,
    };
    const composicaoDepois = composicaoSnapshot(merged);
    const composicaoMudou = composicaoAntes !== composicaoDepois;

    const alteracoes: Array<{ campo: string; valorAnterior: string; valorNovo: string }> = [];

    for (const campo of CAMPOS_HISTORICO) {
      if (campo === 'salarioBase' && composicaoMudou) continue;
      if (body[campo] !== undefined) {
        const anterior = valorParaString(campo, existing[campo]);
        const novo = valorParaString(campo, body[campo]);
        if (anterior !== novo) {
          alteracoes.push({ campo, valorAnterior: anterior, valorNovo: novo });
        }
      }
    }
    if (composicaoMudou) {
      alteracoes.push({
        campo: 'composicaoSalarial',
        valorAnterior: composicaoAntes,
        valorNovo: composicaoDepois,
      });
    }

    const alteradoPor = rh!.userId;

    // Avanço do período aquisitivo ao registrar/atualizar gozo de férias
    let feriasData: {
      dataGozoFerias?: Date | null;
      statusFerias?: string;
      diasFeriasGozados?: number;
      dataInicioFerias?: Date;
    } = {};
    if (dataGozoFerias !== undefined || statusFerias !== undefined || diasFeriasGozados !== undefined) {
      const gozoNovo = dataGozoFerias !== undefined
        ? (dataGozoFerias ? new Date(dataGozoFerias) : null)
        : existing.dataGozoFerias;

      if (dataGozoFerias !== undefined) {
        feriasData.dataGozoFerias = gozoNovo;
      }
      if (diasFeriasGozados !== undefined) {
        feriasData.diasFeriasGozados = Number(diasFeriasGozados);
      }
      // Registrar gozo → status gozadas (salvo se o cliente mandar outro)
      if (statusFerias !== undefined) {
        feriasData.statusFerias = statusFerias;
      } else if (gozoNovo) {
        feriasData.statusFerias = 'gozadas';
      }

      // Alinha o período aquisitivo à data de gozo (avança N anos se necessário)
      if (gozoNovo && (existing.dataAdmissao || existing.dataInicioFerias)) {
        const alvo = inicioAquisitivoAposGozo(gozoNovo, {
          dataAdmissao: existing.dataAdmissao,
          dataInicioFerias: existing.dataInicioFerias,
        });
        const atual = existing.dataInicioFerias;
        if (!atual || !sameUtcDay(alvo, new Date(atual))) {
          feriasData.dataInicioFerias = alvo;
        }
      }
    }

    const funcionario = await prisma.$transaction(async (tx) => {
      const updated = await tx.rhFuncionario.update({
        where: { id },
        data: {
          ...(nome !== undefined && { nome: nome.trim() }),
          ...(cpfLimpo !== undefined && { cpf: cpfLimpo || null }),
          ...(email !== undefined && { email: email || null }),
          ...(telefone !== undefined && { telefone: telefone || null }),
          ...(nascStr !== undefined && {
            dataNascimento: nascStr ? new Date(nascStr) : null,
          }),
          ...(admissaoStr !== undefined && {
            dataAdmissao: admissaoStr ? new Date(admissaoStr) : null,
          }),
          ...(cargoIdNorm !== undefined && { cargoId: cargoIdNorm }),
          ...(lojaIdNorm !== undefined && { lojaId: lojaIdNorm }),
          ...(salarioBase !== undefined && { salarioBase: Number(salarioBase) }),
          ...(valorAlimentacao !== undefined && { valorAlimentacao: Number(valorAlimentacao) }),
          ...(valorVT !== undefined && { valorVT: Number(valorVT) }),
          ...(cargoResponsabilidade !== undefined && {
            cargoResponsabilidade: Boolean(cargoResponsabilidade),
          }),
          ...(bonificacaoAssiduidade !== undefined && {
            bonificacaoAssiduidade: Number(bonificacaoAssiduidade),
          }),
          ...(escala !== undefined && { escala }),
          ...(turno !== undefined && { turno }),
          ...(horarioEntrada !== undefined && { horarioEntrada }),
          ...(horarioSaida !== undefined && { horarioSaida }),
          ...(horarioDigest !== undefined &&
            /^\d{2}:\d{2}$/.test(String(horarioDigest)) && { horarioDigest: String(horarioDigest) }),
          ...(diasFolga !== undefined && { diasFolga }),
          ...(domingoFolga !== undefined && { domingoFolga: domingoFolga || null }),
          ...(observacoes !== undefined && { observacoes: observacoes || null }),
          ...(ativo !== undefined && { ativo }),
          ...(numeroFolhaNorm !== undefined && { numeroFolha: numeroFolhaNorm }),
          ...feriasData,
          ...experienciaData,
        },
        include: INCLUDE,
      });

      if (alteracoes.length > 0) {
        await tx.rhHistoricoFuncionario.createMany({
          data: alteracoes.map((a) => ({
            userId: rh!.userId,
            funcionarioId: id,
            campo: a.campo,
            valorAnterior: a.valorAnterior,
            valorNovo: a.valorNovo,
            alteradoPor,
            motivo: motivo || null,
          })),
        });
      }

      return updated;
    });

    const bonificacoesComposicao = await carregarBonificacoesComposicao(id);

    return NextResponse.json(
      enrichFuncionario(
        funcionario,
        funcionario.cargo?.ratPct ?? 1.0,
        funcionario.loja?.fap ?? 1.0,
        bonificacoesComposicao
      )
    );
  } catch (err) {
    console.error('[PATCH /api/rh/funcionarios/[id]]', err);
    return NextResponse.json({ error: 'Erro interno' }, { status: 500 });
  }
}

export async function DELETE(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  try {
    const { id } = await params;
    const rh = await rhGetUser();
    if (!rh) return NextResponse.json({ error: 'Não autorizado' }, { status: 401 });

    const permanent = req.nextUrl.searchParams.get('permanent') === 'true';

    const existing = await prisma.rhFuncionario.findFirst({
      where: { id, userId: rh!.userId },
    });
    if (!existing)
      return NextResponse.json({ error: 'Funcionário não encontrado' }, { status: 404 });

    if (permanent) {
      // Exclusão definitiva — só permitida para funcionários já inativos
      if (existing.ativo)
        return NextResponse.json(
          { error: 'Desative o funcionário antes de excluir permanentemente' },
          { status: 400 }
        );
      await prisma.rhFuncionario.delete({ where: { id } });
      return NextResponse.json({ ok: true });
    }

    // Soft delete — desativar
    const alteradoPor = rh!.userId;
    await prisma.$transaction(async (tx) => {
      await tx.rhFuncionario.update({ where: { id }, data: { ativo: false } });
      await tx.rhHistoricoFuncionario.create({
        data: {
          userId: rh!.userId,
          funcionarioId: id,
          campo: 'ativo',
          valorAnterior: 'Ativo',
          valorNovo: 'Inativo',
          alteradoPor,
        },
      });
    });

    return NextResponse.json({ ok: true });
  } catch (err) {
    console.error('[DELETE /api/rh/funcionarios/[id]]', err);
    return NextResponse.json({ error: 'Erro interno' }, { status: 500 });
  }
}
